import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 6
    records = list(csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    ))

    def clean_cell(value):
        return value.strip()

    def is_label(value):
        value = value.strip()
        return bool(value) and len(value.split()) <= 3 and bool(
            re.fullmatch(r"[A-Za-z_][A-Za-z_ ]*", value)
        )

    header_index = None
    columns = None

    for index, record in enumerate(records):
        if not record:
            continue
        cells = [clean_cell(cell) for cell in record]
        first = cells[0]

        if first.startswith("#"):
            cells[0] = first[1:].strip()
            if len(cells) >= 2 and all(is_label(cell) for cell in cells):
                header_index = index
                columns = cells
                break
        elif len(cells) >= 2 and all(is_label(cell) for cell in cells):
            header_index = index
            columns = cells
            break

    if columns is None:
        columns = [f"Column{i}" for i in range(1, expected_width + 1)]
        data_records = records
    else:
        data_records = records[header_index + 1:]

    rows = []
    for record in data_records:
        if not record:
            continue

        values = [clean_cell(value) for value in record]
        if not any(values):
            continue
        if values[0].startswith("#"):
            continue

        if len(values) > len(columns):
            for number in range(len(columns) + 1, len(values) + 1):
                columns.append(f"Column{number}")
        values.extend([""] * (len(columns) - len(values)))
        rows.append(values)

    return {"columns": columns, "rows": rows}
